DiceWarrior.SharedWorld.Editor.CompetitionAuthoring.Build();
var scene=UnityEditor.SceneManagement.EditorSceneManager.GetActiveScene();
var all=scene.GetRootGameObjects().SelectMany(r=>r.GetComponentsInChildren<UnityEngine.Transform>(true));
var apps=all.SelectMany(t=>t.GetComponents<DiceWarrior.SharedWorld.CompetitionApp>()).ToArray();
var manager=all.SelectMany(t=>t.GetComponents<FateDice.UIManager>()).Single();
var missing=all.Sum(t=>UnityEditor.GameObjectUtility.GetMonoBehavioursWithMissingScriptCount(t.gameObject));
if(apps.Length!=1 || manager.prefabs.Length!=1 || !(manager.prefabs[0] is DiceWarrior.SharedWorld.CompetitionScreen) || missing!=0) throw new System.InvalidOperationException("Main scene contract failed");
return new {scene=scene.path,sceneGuid=UnityEditor.AssetDatabase.AssetPathToGUID(scene.path),appCount=apps.Length,uiCount=manager.prefabs.Length,missingScripts=missing,config=UnityEditor.AssetDatabase.GetAssetPath(apps[0].combatConfig),prefabGuid=UnityEditor.AssetDatabase.AssetPathToGUID(DiceWarrior.SharedWorld.Editor.CompetitionAuthoring.PrefabPath),dirty=scene.isDirty,roots=scene.GetRootGameObjects().Select(r=>r.name).ToArray()};
